// generated by make_stats.py from stats.html — edit stats.html instead
export default "<!doctype html>\n<html lang=\"th\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>แอป JAC — ความเคลื่อนไหว</title>\n<style>\n:root{ --bg:#F2F3EE; --card:#FBFBF8; --ink:#1E2A26; --mute:#6B7470; --line:#DFE2DA; --bar:#E7A400; --bar2:#3B82C4; --ok:#1F9D55; --soft:#EEF0EA }\n@media (prefers-color-scheme: dark){ :root{ --bg:#141816; --card:#1D2320; --ink:#E9EEEA; --mute:#9AA59F; --line:#2E3632; --soft:#252C29 } }\n*{ box-sizing:border-box } body{ margin:0; background:var(--bg); color:var(--ink); font:15px/1.5 system-ui, 'Noto Sans Thai', sans-serif }\nmain{ max-width:900px; margin:0 auto; padding:16px 16px 50px } h1{ font-size:1.15rem; margin:4px 0 2px } .sub{ color:var(--mute); font-size:.82rem }\n.live{ display:flex; align-items:center; gap:10px; background:var(--card); border:1px solid var(--line); border-radius:16px; padding:14px 16px; margin:14px 0 }\n.dot{ width:12px; height:12px; border-radius:50%; background:#B7BDB9; flex:none } .dot.on{ background:#22C55E; box-shadow:0 0 0 0 rgba(34,197,94,.6); animation:p 1.6s infinite }\n@keyframes p{ to{ box-shadow:0 0 0 10px rgba(34,197,94,0) } }\n.live b{ font-size:1.4rem } .kpis{ display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:10px }\n.k{ background:var(--card); border:1px solid var(--line); border-radius:14px; padding:12px 14px } .k b{ display:block; font-size:1.6rem; line-height:1.2 } .k span{ color:var(--mute); font-size:.8rem }\nh2{ font-size:1rem; margin:22px 0 8px } .card{ background:var(--card); border:1px solid var(--line); border-radius:14px; padding:14px }\n.chart{ display:flex; align-items:flex-end; gap:6px; height:150px; padding-top:18px } .col{ flex:1; display:flex; flex-direction:column; align-items:center; justify-content:flex-end; height:100%; min-width:0 }\n.col .v{ font-size:.68rem; color:var(--mute) } .col i{ display:block; width:100%; max-width:34px; background:var(--bar); border-radius:6px 6px 2px 2px; min-height:2px }\n.col.today i{ background:var(--bar2) } .col .d{ font-size:.66rem; color:var(--mute); margin-top:4px; white-space:nowrap }\n.legend{ font-size:.76rem; color:var(--mute); margin-top:8px }\ntable{ width:100%; border-collapse:collapse; font-size:.86rem } th,td{ text-align:left; padding:7px 4px; border-bottom:1px solid var(--line) } th{ color:var(--mute); font-weight:600 } td.n{ text-align:right }\n.pass{ color:var(--ok); font-weight:700 } .hours{ display:grid; grid-template-columns:repeat(24,1fr); gap:2px; align-items:end; height:70px }\n.hours i{ display:block; background:var(--bar2); border-radius:3px 3px 0 0; min-height:2px } .hl{ display:grid; grid-template-columns:repeat(24,1fr); font-size:.6rem; color:var(--mute); text-align:center }\n.nm{ font-weight:700 } .av{ width:30px; height:30px; border-radius:50%; object-fit:cover; display:inline-grid; place-items:center; background:var(--soft); vertical-align:middle; margin-right:8px; font-size:.8rem; font-weight:700 } .muted{ color:var(--mute); font-size:.78rem } .ok{ color:var(--ok); font-weight:700 } .ng{ color:#D9480F; font-weight:700 } .tw{ overflow-x:auto }\n.empty{ color:var(--mute); text-align:center; padding:20px }\n</style>\n</head>\n<body><main>\n<h1>📊 แอป JAC — ความเคลื่อนไหว</h1>\n<div class=\"sub\">ชื่อตามที่แต่ละคนตั้งในแอป (ไม่ตั้ง = ไม่ระบุชื่อ, 1 เครื่อง = 1 คน) · เวลาญี่ปุ่น · อัปเดตเองทุก 30 วินาที</div>\n<div class=\"live\" id=\"live\"><span class=\"dot\"></span><span>กำลังโหลด…</span></div>\n<div id=\"gate\" class=\"card\" style=\"display:none;margin:14px 0\"><b>🔒 ใส่รหัสผ่านเพื่อดูหน้านี้</b><div style=\"display:flex;gap:8px;margin-top:10px\"><input id=\"key\" type=\"password\" style=\"flex:1;padding:10px 12px;border-radius:10px;border:1px solid var(--line);font:inherit;background:var(--card);color:var(--ink)\"><button id=\"go\" style=\"padding:10px 16px;border-radius:10px;border:none;background:var(--bar);font:inherit;font-weight:700\">เปิด</button></div><div id=\"gmsg\" class=\"sub\" style=\"margin-top:6px\"></div></div>\n<div class=\"kpis\" id=\"kpis\"></div>\n<h2>👥 รายชื่อ (ตามชื่อเล่นที่ตั้งในแอป)</h2>\n<div class=\"card\" id=\"people\"></div>\n<h2>14 วันล่าสุด — จำนวนเครื่องที่ทำแบบทดสอบ</h2>\n<div class=\"card\"><div class=\"chart\" id=\"chart\"></div><div class=\"legend\">แท่งสีน้ำเงิน = วันนี้ · ตัวเลขบนแท่ง = จำนวนเครื่อง</div></div>\n<h2>วันนี้แยกตามภาค</h2>\n<div class=\"card\" id=\"parts\"></div>\n<h2>สอบจำลอง 14 วัน</h2>\n<div class=\"card\" id=\"mocks\"></div>\n<h2>ช่วงเวลาที่ทำบ่อย (7 วัน)</h2>\n<div class=\"card\"><div class=\"hours\" id=\"hours\"></div><div class=\"hl\" id=\"hl\"></div></div>\n<h2>กิจกรรมล่าสุด</h2>\n<div class=\"card\" id=\"recent\"></div>\n</main>\n<script>\nvar PART = { gakka: 'ทฤษฎี', jitsugi: 'ปฏิบัติ 土木', life: 'ปฏิบัติ ไลฟ์ไลน์', '': '—' };\nvar MODE = { real: 'สอบจำลอง', mini: 'ทดสอบย่อย', all: 'ทำทุกข้อ', wrong: 'ข้อที่เคยผิด', fav: 'ติดดาว', weak: 'จุดอ่อน', review: 'ทบทวน', hot: '🔥 ข้อที่ออก' };\nfunction $(id){ return document.getElementById(id); }\nfunction pct(s, n){ return n ? Math.round(s / n * 100) + '%' : '—'; }\nfunction ago(ts, now){ var m = Math.round((now - ts) / 60000); if (m < 1) return 'เมื่อสักครู่'; if (m < 60) return m + ' นาทีที่แล้ว'; var h = Math.round(m / 60); if (h < 24) return h + ' ชม.ที่แล้ว'; return Math.round(h / 24) + ' วันที่แล้ว'; }\nfunction esc(v){ return String(v == null ? '' : v).replace(/[&<>\"']/g, function(c){ return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '\"':'&quot;', \"'\":'&#39;' }[c]; }); }\nfunction pc(v){ return v == null ? '—' : '<span class=\"' + (v >= 75 ? 'ok' : 'ng') + '\">' + v + '%</span>'; }\nfunction renderPeople(d){\n  var ps = d.people || [];\n  $('people').innerHTML = ps.length ? '<div class=\"tw\"><table><tr><th>ชื่อ</th><th>ล่าสุด</th><th class=\"n\">วันนี้</th><th class=\"n\">7 วัน</th><th class=\"n\">ถูกรวม</th><th class=\"n\">สอบจำลองล่าสุด</th></tr>' + ps.map(function(p){\n    var lm = p.mock_pct != null ? [p.mock_pct, p.mock_part] : null;\n    var on = d.now - p.last < 5 * 60000;\n    return '<tr><td>' + (p.avatar ? '<img class=\"av\" src=\"' + p.avatar + '\" alt=\"\">' : '<span class=\"av\">' + esc((p.name || '?').slice(0, 1)) + '</span>') + '<span class=\"nm\">' + (p.name ? esc(p.name) : '<span class=\"muted\">ไม่ระบุชื่อ</span>') + '</span>' + (on ? ' 🟢' : '') + '</td><td class=\"muted\">' + ago(p.last, d.now) + '</td>' +\n      '<td class=\"n\">' + (p.n_today ? p.n_today + ' ข้อ<br><span class=\"muted\">' + Math.round(p.s_today / p.n_today * 100) + '%</span>' : '<span class=\"muted\">—</span>') + '</td>' +\n      '<td class=\"n\">' + (p.n_7 || '<span class=\"muted\">0</span>') + '</td><td class=\"n\">' + (p.n_all ? pc(Math.round(p.s_all / p.n_all * 100)) : '—') + '</td>' +\n      '<td class=\"n\">' + (lm ? pc(+lm[0]) + '<br><span class=\"muted\">' + (PART[lm[1]] || '') + '</span>' : '—') + '</td></tr>';\n  }).join('') + '</table></div><div class=\"legend\">🟢 = เปิดแอปอยู่ตอนนี้ · คนที่ตั้งชื่อเดียวกันในหลายเครื่องจะรวมเป็นแถวเดียว</div>' : '<div class=\"empty\">ยังไม่มีข้อมูล</div>';\n}\nfunction render(d){\n  renderPeople(d);\n  var liveN = d.live.reduce(function(a, x){ return a + x.c; }, 0);\n  $('live').innerHTML = '<span class=\"dot ' + (liveN ? 'on' : '') + '\"></span><span><b>' + liveN + '</b> เครื่องเปิดแอปอยู่ตอนนี้' +\n    (liveN ? ' <span class=\"sub\">(' + d.live.map(function(x){ return (PART[x.part] || x.part) + ' ' + x.c; }).join(' · ') + ')</span>' : '') + '<br><span class=\"sub\">นับเครื่องที่ใช้งานใน 5 นาทีล่าสุด</span></span>';\n  var t = d.t || {};\n  $('kpis').innerHTML = [['เปิดแอปวันนี้', d.opensToday + ' เครื่อง'], ['ทำแบบทดสอบวันนี้', (t.devs || 0) + ' เครื่อง'], ['ชุดที่ทำวันนี้', t.quizzes || 0], ['ข้อที่ตอบวันนี้', t.n || 0], ['ตอบถูกเฉลี่ยวันนี้', pct(t.s, t.n)], ['ผู้ใช้ 7 วัน', d.devs7 + ' เครื่อง']]\n    .map(function(k){ return '<div class=\"k\"><b>' + k[1] + '</b><span>' + k[0] + '</span></div>'; }).join('');\n  var byDay = {}; d.days.forEach(function(x){ byDay[x.day] = x; });\n  var list = []; for (var i = 13; i >= 0; i--) { var day = new Date(d.now + 9 * 3600e3 - i * 864e5).toISOString().slice(0, 10); list.push({ day: day, v: byDay[day] ? byDay[day].devs : 0 }); }\n  var max = Math.max.apply(null, list.map(function(x){ return x.v; }).concat([1]));\n  $('chart').innerHTML = list.map(function(x){ return '<div class=\"col ' + (x.day === d.today ? 'today' : '') + '\"><span class=\"v\">' + (x.v || '') + '</span><i style=\"height:' + Math.round(x.v / max * 100) + '%\"></i><span class=\"d\">' + +x.day.slice(8) + '</span></div>'; }).join('');\n  $('parts').innerHTML = d.parts.length ? '<table><tr><th>ภาค</th><th class=\"n\">ชุด</th><th class=\"n\">ข้อ</th><th class=\"n\">ถูก</th></tr>' + d.parts.map(function(p){ return '<tr><td>' + (PART[p.part] || p.part) + '</td><td class=\"n\">' + p.quizzes + '</td><td class=\"n\">' + p.n + '</td><td class=\"n\">' + pct(p.s, p.n) + '</td></tr>'; }).join('') + '</table>' : '<div class=\"empty\">วันนี้ยังไม่มีใครทำแบบทดสอบ</div>';\n  $('mocks').innerHTML = d.mocks.length ? '<table><tr><th>ภาค</th><th class=\"n\">ครั้ง</th><th class=\"n\">ผ่าน 75%</th></tr>' + d.mocks.map(function(m){ return '<tr><td>' + (PART[m.part] || m.part) + '</td><td class=\"n\">' + m.c + '</td><td class=\"n pass\">' + m.pass + ' (' + pct(m.pass, m.c) + ')</td></tr>'; }).join('') + '</table>' : '<div class=\"empty\">ยังไม่มีการสอบจำลอง</div>';\n  var hs = []; for (var h = 0; h < 24; h++) hs.push(0); d.hours.forEach(function(x){ hs[x.h] = x.c; }); var hm = Math.max.apply(null, hs.concat([1]));\n  $('hours').innerHTML = hs.map(function(c){ return '<i style=\"height:' + Math.round(c / hm * 100) + '%\" title=\"' + c + '\"></i>'; }).join('');\n  $('hl').innerHTML = hs.map(function(c, h){ return '<span>' + (h % 3 ? '' : h) + '</span>'; }).join('');\n  $('recent').innerHTML = d.recent.length ? '<table><tr><th>เวลา</th><th>ใคร</th><th>ภาค</th><th>โหมด</th><th class=\"n\">คะแนน</th></tr>' + d.recent.map(function(r){ return '<tr><td>' + ago(r.ts, d.now) + '</td><td>' + esc(r.name || 'ไม่ระบุชื่อ') + '</td><td>' + (PART[r.part] || r.part) + '</td><td>' + (MODE[r.mode] || r.mode) + '</td><td class=\"n\">' + r.s + '/' + r.n + ' (' + pct(r.s, r.n) + ')</td></tr>'; }).join('') + '</table>' : '<div class=\"empty\">ยังไม่มีข้อมูล</div>';\n}\nvar KEY = ''; try { KEY = localStorage.getItem('jac-statskey') || ''; } catch (e) {}\nfunction load(){\n  fetch('/api/stats', { cache: 'no-store', headers: { 'x-key': KEY } }).then(function(r){\n    if (r.status === 401) { $('gate').style.display = 'block'; $('live').style.display = 'none'; if (KEY) $('gmsg').textContent = 'รหัสผ่านไม่ถูกต้อง'; throw 'key'; }\n    return r.json();\n  }).then(function(d){ $('gate').style.display = 'none'; $('live').style.display = ''; render(d); }).catch(function(e){ if (e !== 'key') $('live').innerHTML = '<span class=\"dot\"></span><span>โหลดข้อมูลไม่ได้ — ลองใหม่อีกครั้ง</span>'; });\n}\n$('go').onclick = function(){ KEY = $('key').value.trim(); try { localStorage.setItem('jac-statskey', KEY); } catch (e) {} load(); };\n$('key').onkeydown = function(e){ if (e.key === 'Enter') $('go').click(); };\nload(); setInterval(function(){ if (KEY) load(); }, 30000);\n</script>\n</body></html>\n";
